using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.ChatCompletion;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Tests
{
    public class VertexAIKernelBuilderExtensionsTests
    {
        [Fact]
        public void AddVertexAIGeminiChatCompletion_WithBearerTokenProvider_RegistersService()
        {
            // Arrange
            var kernelBuilderMock = new Mock<IKernelBuilder>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            var httpClient = new HttpClient();

            kernelBuilderMock.Setup(kb => kb.Services).Returns(new ServiceCollection());
            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactoryMock.Object);

            var modelId = "test-model";
            var bearerTokenProvider = new Func<ValueTask<string>>(() => new ValueTask<string>("test-token"));
            var location = "test-location";
            var projectId = "test-project-id";

            // Act
            var result = VertexAIKernelBuilderExtensions.AddVertexAIGeminiChatCompletion(
                kernelBuilderMock.Object,
                modelId,
                bearerTokenProvider,
                location,
                projectId,
                httpClient: httpClient);

            // Assert
            var serviceDescriptor = kernelBuilderMock.Object.Services.FirstOrDefault(descriptor =>
                descriptor.ServiceType == typeof(IChatCompletionService) &&
                descriptor.ImplementationFactory != null);

            Assert.NotNull(serviceDescriptor);
            Assert.Equal(ServiceLifetime.Singleton, serviceDescriptor.Lifetime);
            Assert.Equal("test-service-id", serviceDescriptor.ServiceKey);

            var service = serviceDescriptor.ImplementationFactory(serviceProviderMock.Object, null);
            Assert.IsType<VertexAIGeminiChatCompletionService>(service);
        }

        [Fact]
        public void AddVertexAIGeminiChatCompletion_WithBearerKey_RegistersService()
        {
            // Arrange
            var kernelBuilderMock = new Mock<IKernelBuilder>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            var httpClient = new HttpClient();

            kernelBuilderMock.Setup(kb => kb.Services).Returns(new ServiceCollection());
            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactoryMock.Object);

            var modelId = "test-model";
            var bearerKey = "test-bearer-key";
            var location = "test-location";
            var projectId = "test-project-id";

            // Act
            var result = VertexAIKernelBuilderExtensions.AddVertexAIGeminiChatCompletion(
                kernelBuilderMock.Object,
                modelId,
                bearerKey,
                location,
                projectId,
                httpClient: httpClient);

            // Assert
            var serviceDescriptor = kernelBuilderMock.Object.Services.FirstOrDefault(descriptor =>
                descriptor.ServiceType == typeof(IChatCompletionService) &&
                descriptor.ImplementationFactory != null);

            Assert.NotNull(serviceDescriptor);
            Assert.Equal(ServiceLifetime.Singleton, serviceDescriptor.Lifetime);
            Assert.Equal("test-service-id", serviceDescriptor.ServiceKey);

            var service = serviceDescriptor.ImplementationFactory(serviceProviderMock.Object, null);
            Assert.IsType<VertexAIGeminiChatCompletionService>(service);
        }
    }
}
```

The error indicates that the `ImplementationFactory` delegate does not take 2 arguments. This is because the `AddKeyedSingleton` method in `ServiceCollection` does not use a delegate that takes two arguments. Instead, it uses a delegate that takes one argument of type `IServiceProvider`.

Let's correct the test to use the correct delegate signature. Additionally, we need to ensure that the `VertexAIGeminiChatCompletionService` type is correctly referenced.

